289	        MvcResult first = mockMvc.perform(post("/api/batches/" + batchKey + "/approvals")
290	                        .header("X-Actor-Id", "qa").header("X-Approval-Role", "QUALITY")
291	                        .contentType(MediaType.APPLICATION_JSON).content(body))
292	                .andExpect(status().isCreated()).andReturn();
293	        MvcResult replay = mockMvc.perform(post("/api/batches/" + batchKey + "/approvals")
294	                        .header("X-Actor-Id", "qa").header("X-Approval-Role", "QUALITY")
295	                        .contentType(MediaType.APPLICATION_JSON).content(body))
296	                .andExpect(status().isCreated()).andReturn();
297	        assertEquals(first.getResponse().getContentAsString(),
298	                replay.getResponse().getContentAsString());
299	        // 同 commandKey 换操作人 → 409
300	        mockMvc.perform(post("/api/batches/" + batchKey + "/approvals")
301	                        .header("X-Actor-Id", "qa2").header("X-Approval-Role", "QUALITY")
302	                        .contentType(MediaType.APPLICATION_JSON).content(body))
303	                .andExpect(status().isConflict());
