409	    @Test
410	    void concurrentAncestorRecallAndDescendantFinalApproval_commitOrderDecides() throws Exception {
411	        String root = "BK-CRA-R-" + unique();
412	        createBatch(root, List.of("t1"), 201);
413	        releaseBatch(root, "insp-1");
414	        String child = "BK-CRA-C-" + unique();
415	        split(root, "CK-CRA-S", List.of(new String[]{child, "L1"},
416	                new String[]{"BK-CRA-C2-" + unique(), "L2"}), 201);
417	        submitTest(child, "t1", "PASS", "insp-2", 201);
418	        approve(child, "qa-1", "QUALITY", "CK-CRA-A1", 201);
419	
420	        List<Future<Integer>> results = runConcurrent(
421	                () -> callStatus(post("/api/batches/" + child + "/approvals")
422	                        .header("X-Actor-Id", "ops-1").header("X-Approval-Role", "OPERATIONS")
423	                        .contentType(MediaType.APPLICATION_JSON)
424	                        .content("{\"commandKey\":\"CK-CRA-A2\"}")),
425	                () -> callStatus(post("/api/batches/" + root + "/recall")
426	                        .header("X-Actor-Id", "u")
427	                        .contentType(MediaType.APPLICATION_JSON)
428	                        .content("{\"commandKey\":\"CK-CRA-R\",\"reason\":\"根批召回\"}"))
429	        );
430	
431	        int finalApproval = results.get(0).get(30, TimeUnit.SECONDS);
432	        int recall = results.get(1).get(30, TimeUnit.SECONDS);
433	        assertEquals(201, recall, "SPLIT 根批始终可召回");
434	        if (finalApproval == 201) {
435	            // 批准先提交：子批 RELEASED，随后召回使其不可用但状态不改写
436	            assertEquals("RELEASED", currentStatus(child));
437	            assertFalse(availableKeys().contains(child));
438	        } else {
439	            // 召回先提交：后代新增批准被拦截 422，子批停留 RELEASE_REVIEW
440	            assertEquals(422, finalApproval);
441	            assertEquals("RELEASE_REVIEW", currentStatus(child));
442	        }
443	        // 无论哪种顺序，都不会出现"批准成功且子批仍可用"
444	        assertFalse(finalApproval == 201 && availableKeys().contains(child));
445	    }
